    treatmentProtocols: [
      { condition: 'Vamana (Emesis Therapy)', treatment: 'Poorvakarma (3-5 days) + Vamana (1 day) + Samsarjana (7 days)', herbs: ['Madanaphala Pippali (emetic drug)', 'Yavakshara (alkali)', 'Saindhava (rock salt)', 'Honey', 'Vacha (Acorus calamus)'], dosage: 'Madanaphala Pippali: 3-5g with honey and Yavakshara; repeat until adequate emesis', duration: 'Total: 11-13 days (3-5 prep + 1 procedure + 7 Samsarjana)', precautions: ['Assess Bala and Agni before', 'Heavy food previous night', 'Monitor for Samyak/Ayoga/Atiyoga', 'Stop when Pitta appears in vomit'] },
      { condition: 'Basti (Medicated Enema)', treatment: 'Poorvakarma (3-5 days) + Basti course (8-16 days) + Samsarjana (7 days)', herbs: ['Dashamula Kwatha (decoction)', 'Eranda Taila (castor oil)', 'Saindhava (rock salt)', 'Honey', 'Medicated oils based on condition'], dosage: 'Niruha Basti: 480-960ml; Anuvasana Basti: 60-120ml oil', duration: 'Kala Basti: 16 days (8 Niruha + 8 Anuvasana); Karma Basti: 30 days', precautions: ['Proper Snehana before Basti', 'Assess Koshtha for dose', 'Monitor retention time', 'Follow Samsarjana strictly'] },
      { condition: 'Vata Shamana Ch16', treatment: 'Snehana plus Swedana plus Basti', herbs: ['Ashwagandha', 'Bala', 'Eranda', 'Shunthi', 'Ghee', 'Sesame oil'], dosage: 'Snehapana increasing doses 3-7 days. Basti 600-900ml', duration: '8-30 days depending on severity', precautions: ['Assess Agni before Snehapana', 'Contraindicated in Ama condition'] },
      { condition: 'Pitta Shamana Ch16', treatment: 'Virechana preceded by internal oleation', herbs: ['Trivrit', 'Amalaki', 'Draksha', 'Guduchi', 'Ghee', 'Sandalwood'], dosage: 'Snehapana with ghee 3-5 days then Virechana', duration: 'Single day Virechana plus 7-day Samsarjana', precautions: ['Avoid in pregnancy', 'Assess Rakta-Pitta involvement'] },
      { condition: 'Kapha Shamana Ch16', treatment: 'Vamana preceded by internal oleation', herbs: ['Madanaphala', 'Jimutaka', 'Yastimadhu', 'Vacha', 'Honey', 'Rock salt'], dosage: 'Madanaphala kalka with honey', duration: 'Single day Vamana plus 7-day Samsarjana', precautions: ['Contraindicated in Pitta conditions', 'Monitor emesis quality'] },
      { condition: 'Vata Shamana Ch16', treatment: 'Snehana plus Swedana plus Basti', herbs: ['Ashwagandha', 'Bala', 'Eranda', 'Shunthi', 'Ghee', 'Sesame oil'], dosage: 'Snehapana increasing doses 3-7 days. Basti 600-900ml', duration: '8-30 days depending on severity', precautions: ['Assess Agni before Snehapana', 'Contraindicated in Ama condition'] },
      { condition: 'Pitta Shamana Ch16', treatment: 'Virechana preceded by internal oleation', herbs: ['Trivrit', 'Amalaki', 'Draksha', 'Guduchi', 'Ghee', 'Sandalwood'], dosage: 'Snehapana with ghee 3-5 days then Virechana', duration: 'Single day Virechana plus 7-day Samsarjana', precautions: ['Avoid in pregnancy', 'Assess Rakta-Pitta involvement'] },
      { condition: 'Kapha Shamana Ch16', treatment: 'Vamana preceded by internal oleation', herbs: ['Madanaphala', 'Jimutaka', 'Yastimadhu', 'Vacha', 'Honey', 'Rock salt'], dosage: 'Madanaphala kalka with honey', duration: 'Single day Vamana plus 7-day Samsarjana', precautions: ['Contraindicated in Pitta conditions', 'Monitor emesis quality'] },
    ],
    additionalTopics: [
      { title: 'Vamana Karma Detailed Protocol', content: 'Day before: Kapha-aggravating dinner. Morning: Madanaphala Kalka (3-5g) with honey + Yastimadhu Kwatha. Expected: 4-8 bouts. Proper sign: Kapha first, then Pitta appears - stop. Samsarjana: 7 days. Complications: Ati-Yoga, Ayoga, Raktayukta.', clinicalRelevance: 'Proper Vamana protocol is essential for Kapha disorders.' },
      { title: 'Virechana Karma Detailed Protocol', content: 'Days 1-5: Snehapana with Ghrita. Day 6: Swedana. Day 7: Virechana with Trivrit (5-10g) + warm milk. Expected: 4-8 purges. Proper sign: Pitta-colored stool, lightness. Samsarjana: 7 days.', clinicalRelevance: 'Proper Virechana protocol essential for Pitta disorders.' },
      { title: 'Basti Karma Detailed Protocol', content: 'Preparation: Snehana + Swedana for 3-7 days. Niruha: Dashamula Kwatha + honey + salt + oil, 480-960ml. Anuvasana: sesame oil, 60-120ml. Schedule: alternate Niruha and Anuvasana. Kala Basti: 16 days. Karma Basti: 30 days.', clinicalRelevance: 'Basti is the most important Panchakarma for Vata disorders.' },
      { title: 'Nasya Karma Detailed Protocol', content: 'Preparation: Shiro Abhyanga + facial Swedana. Types: Virechana Nasya (purgative), Brimhana Nasya (nourishing), Shamana Nasya (pacifying). Dose: 4-8 drops each nostril. Position: head low, supine. Time: morning. Duration: 7-21 days.', clinicalRelevance: 'Nasya is the primary treatment for all head and neck diseases.' },
      { title: 'Raktamokshana Karma Protocol', content: 'Methods: Siravyadha (venepuncture), Jalaukavacharana (leech therapy), Pracchana (scarification). Indications: Raktaja Vyadhi, Vatarakta, Kushtha, Visarpa. Contraindications: pregnancy, anemia, debility. Post-care: rest, light diet.', clinicalRelevance: 'Raktamokshana is indicated for blood-borne and Pitta-Rakta disorders.' },
    ],
    importantVerses: [
      'After proper Snehana and Swedana, perform Shodhana (16.3)',
      'Vamana in the morning (Kapha time) after heavy food (16.4)',
      'Virechana in the afternoon (Pitta time) after light food (16.5)',
      'Basti in morning or evening (Vata time) after Snehana (16.6)',
      'After Shodhana, follow Samsarjana Krama and dietary modification (16.9)',
      'In under-administration, repeat; in over-administration, treat complications (16.11)',
    ],
